def transform(grid):
    H=len(grid); W=len(grid[0]); out=[row[:] for row in grid]
    blocks=[]; used=set()
    for br in range(H):
        for bc in range(W):
            b=grid[br][bc]
            if b==0 or (br,bc) in used: continue
            for s in (3,4,5):
                if br+s>H or bc+s>W: continue  # skip truncated blocks at grid edges
                if not all(grid[br+r][bc+c]==b for r in range(s) for c in range(s) if r in(0,s-1) or c in(0,s-1)): continue
                if br>0 and all(grid[br-1][bc+c]==b for c in range(s)): continue  # part of larger block
                if bc>0 and all(grid[br+r][bc-1]==b for r in range(s)): continue
                ctr=grid[br+s//2][bc+s//2]
                if ctr!=b and ctr!=0 and all(grid[br+r][bc+c]==ctr for r in range(1,s-1) for c in range(1,s-1)):
                    blocks.append((br,bc,s,b,ctr))
                    for r in range(s):
                        for c in range(s): used.add((br+r,bc+c))
                    break
    marks={}; t={}
    for br,bc,s,f,ctr in blocks:
        marks.setdefault(ctr,[]).append((br+s//2,bc+s//2)); t[ctr]=s-2
    for col,pts in marks.items():
        if len(pts)!=4: continue
        rs=sorted({p[0] for p in pts}); cs=sorted({p[1] for p in pts})
        if len(rs)!=2 or len(cs)!=2: continue
        if set(pts)!={(r,c) for r in rs for c in cs}: continue
        r1_,r2_=rs; c1_,c2_=cs; h=t[col]//2
        for c in range(c1_+1,c2_):
            for rr in list(range(r1_-h,r1_+h+1))+list(range(r2_-h,r2_+h+1)):
                if 0<=rr<H and out[rr][c]==0: out[rr][c]=col
        for r in range(r1_+1,r2_):
            for cc in list(range(c1_-h,c1_+h+1))+list(range(c2_-h,c2_+h+1)):
                if 0<=cc<W and out[r][cc]==0: out[r][cc]=col
    return out

